function makeStatusMachine(initial) {
  let status = initial;
  return {
    get() { return status; },
    set(next) {
      if (next === undefined) return status;
      status = next;
      return status;
    },
  };
}

function makeIdFactory(prefix) {
  let n = 0;
  return function nextId() {
    n += 1;
    return prefix + "-" + n;
  };
}
